local MatchCordMaker = {}
local PRODUCTS = {
    hemp_match = { name = "Konopljev prižig", hempCost = 2, saltpeterCost = 1, time = 1, cost = 8, burnRate = 30, durability = 5, description = "Preprost konopljev prižig za ročne topovske." },
    linen_match = { name = "Lneni prižig", linenCost = 2, saltpeterCost = 1, time = 2, cost = 22, burnRate = 40, durability = 8, prestige = 1, description = "Lneni prižig z boljšim zgorevanjem." },
    slow_match = { name = "Počasni prižig", hempCost = 3, saltpeterCost = 2, time = 4, cost = 60, burnRate = 60, durability = 12, prestige = 3, happiness = 1, description = "Počasni prižig za dolge oblege." },
    treated_match = { name = "Obdelani prižig", hempCost = 3, saltpeterCost = 2, charcoalCost = 1, time = 6, cost = 150, burnRate = 75, durability = 18, prestige = 6, happiness = 2, description = "Obdelani prižig z ogljeno korekcijo." },
    silver_dust_match = { name = "Srebrno prašni prižig", hempCost = 3, saltpeterCost = 2, silverCost = 1, charcoalCost = 1, time = 9, cost = 360, burnRate = 90, durability = 25, prestige = 12, happiness = 3, description = "Prižig s srebrnim prahom za zanesljivo prižiganje." },
    royal_ceremonial_match = { name = "Kraljevski slovesni prižig", silkCost = 2, goldCost = 1, silverCost = 1, saltpeterCost = 3, jewelCost = 1, pearlCost = 1, time = 14, cost = 950, burnRate = 100, durability = 35, prestige = 30, happiness = 7, description = "Veliki kraljevski slovesni prižig s svilo, zlatom in biseri za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Prižigarska delavnica", cost = { gold = 220, wood = 110 }, upkeep = 5, qualityBonus = 5 },
    dip_room = { name = "Potorilnica", cost = { gold = 750, wood = 220, stone = 300, saltpeter = 8 }, upkeep = 18, qualityBonus = 18 },
    drying_room = { name = "Sušilnica", cost = { gold = 1800, wood = 280, stone = 500, silver = 30, charcoal = 8 }, upkeep = 42, qualityBonus = 30 },
    royal_match_atelier = { name = "Kraljevski atelje prižigov", cost = { gold = 7500, wood = 500, stone = 800, gold = 60, jewel = 20 }, upkeep = 150, qualityBonus = 55, prestigeBonus = 35 },
}
MatchCordMaker.hempStock = 18; MatchCordMaker.linenStock = 14; MatchCordMaker.saltpeterStock = 16; MatchCordMaker.charcoalStock = 12; MatchCordMaker.silverStock = 8; MatchCordMaker.goldStock = 6; MatchCordMaker.silkStock = 8; MatchCordMaker.jewelStock = 6; MatchCordMaker.pearlStock = 4
MatchCordMaker.productStock = {}; MatchCordMaker.buildings = {}; MatchCordMaker.maker = nil; MatchCordMaker.activeMaking = {}; MatchCordMaker.totalProducts = 0; MatchCordMaker.dayTimer = 0
function MatchCordMaker.init() MatchCordMaker.hempStock=18; MatchCordMaker.linenStock=14; MatchCordMaker.saltpeterStock=16; MatchCordMaker.charcoalStock=12; MatchCordMaker.silverStock=8; MatchCordMaker.goldStock=6; MatchCordMaker.silkStock=8; MatchCordMaker.jewelStock=6; MatchCordMaker.pearlStock=4; MatchCordMaker.productStock={}; MatchCordMaker.buildings={}; MatchCordMaker.maker=nil; MatchCordMaker.activeMaking={}; MatchCordMaker.totalProducts=0; MatchCordMaker.dayTimer=0; print("[MatchCordMaker] Royal Match Cord Maker System initialized (6 products, 4 buildings)") end
function MatchCordMaker.hireMaker(n,s) s=s or math.random(50,90); local c=460+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MatchCordMaker.maker={name=n or ("Prižigar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Prižigar najet: %s (spretnost: %d)",MatchCordMaker.maker.name,s),"success") end; return true end
function MatchCordMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MatchCordMaker.build(id) local ok,e=MatchCordMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MatchCordMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MatchCordMaker.getQualityBonus() local b=0; for _,bd in ipairs(MatchCordMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MatchCordMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.hempCost and MatchCordMaker.hempStock<(d.hempCost or 0) then return false,"Premalo konoplje" end; if d.linenCost and MatchCordMaker.linenStock<(d.linenCost or 0) then return false,"Premalo lana" end; if d.saltpeterCost and MatchCordMaker.saltpeterStock<(d.saltpeterCost or 0) then return false,"Premalo salitre" end; if d.charcoalCost and MatchCordMaker.charcoalStock<(d.charcoalCost or 0) then return false,"Premalo oglja" end; if d.silverCost and MatchCordMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MatchCordMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.silkCost and MatchCordMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.jewelCost and MatchCordMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MatchCordMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MatchCordMaker.buildings==0 then return false,"Potrebna delavnica" end; if not MatchCordMaker.maker then return false,"Potreben prižigar" end; return true end
function MatchCordMaker.make(pt,qty) qty=qty or 10; local ok,e=MatchCordMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.hempCost then MatchCordMaker.hempStock=MatchCordMaker.hempStock-d.hempCost*qty end; if d.linenCost then MatchCordMaker.linenStock=MatchCordMaker.linenStock-d.linenCost*qty end; if d.saltpeterCost then MatchCordMaker.saltpeterStock=MatchCordMaker.saltpeterStock-d.saltpeterCost*qty end; if d.charcoalCost then MatchCordMaker.charcoalStock=MatchCordMaker.charcoalStock-d.charcoalCost*qty end; if d.silverCost then MatchCordMaker.silverStock=MatchCordMaker.silverStock-d.silverCost*qty end; if d.goldCost then MatchCordMaker.goldStock=MatchCordMaker.goldStock-d.goldCost*qty end; if d.silkCost then MatchCordMaker.silkStock=MatchCordMaker.silkStock-d.silkCost*qty end; if d.jewelCost then MatchCordMaker.jewelStock=MatchCordMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MatchCordMaker.pearlStock=MatchCordMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MatchCordMaker.maker then t=math.max(1,t-math.floor(MatchCordMaker.maker.skill/12)) end; table.insert(MatchCordMaker.activeMaking,{id="match_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,burnRate=d.burnRate or 0,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MatchCordMaker.completeMaking(m) local q=1.0+(MatchCordMaker.getQualityBonus()/100); if MatchCordMaker.maker then q=q+(MatchCordMaker.maker.skill/180) end; q=math.min(2.0,q); MatchCordMaker.productStock[m.productType]=(MatchCordMaker.productStock[m.productType] or 0)+m.quantity; MatchCordMaker.totalProducts=MatchCordMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MatchCordMaker.maker then MatchCordMaker.maker.itemsMade=MatchCordMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then MatchCordMaker.maker.skill=math.min(100,MatchCordMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Prižigi izdelani: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"matchcord.completed",{productName=m.productName,burnRate=m.burnRate,durability=m.durability}) end end
function MatchCordMaker.update(dt) if not _G.state then return end; MatchCordMaker.dayTimer=MatchCordMaker.dayTimer+dt; if MatchCordMaker.dayTimer>=30 then MatchCordMaker.dayTimer=0; for i=#MatchCordMaker.activeMaking,1,-1 do local m=MatchCordMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MatchCordMaker.completeMaking(m); table.remove(MatchCordMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MatchCordMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MatchCordMaker.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MatchCordMaker.getStats() return {hempStock=MatchCordMaker.hempStock,linenStock=MatchCordMaker.linenStock,saltpeterStock=MatchCordMaker.saltpeterStock,charcoalStock=MatchCordMaker.charcoalStock,silverStock=MatchCordMaker.silverStock,goldStock=MatchCordMaker.goldStock,silkStock=MatchCordMaker.silkStock,jewelStock=MatchCordMaker.jewelStock,pearlStock=MatchCordMaker.pearlStock,productStock=MatchCordMaker.productStock,numBuildings=#MatchCordMaker.buildings,hasMaker=MatchCordMaker.maker~=nil,makerName=MatchCordMaker.maker and MatchCordMaker.maker.name or "—",makerSkill=MatchCordMaker.maker and MatchCordMaker.maker.skill or 0,activeMaking=#MatchCordMaker.activeMaking,totalProducts=MatchCordMaker.totalProducts} end
return MatchCordMaker
